<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = 200005;
const int INFINITY_VAL = 1000000007;

long long X, Y, total, numerator = -1, denominator = -1;

void evaluate(long long a, int b) {
    if (a < 0) return;
    if (numerator == -1) {
        numerator = a;
        denominator = b;
        return;
    }
    long long diff1 = abs(denominator * X - numerator * Y) * b;
    long long diff2 = abs(b * X - a * Y) * denominator;
    if (diff1 > diff2) {
        numerator = a;
        denominator = b;
    } else if (diff1 == diff2 && (b < denominator || (b == denominator && a < numerator))) {
        numerator = a;
        denominator = b;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> X >> Y >> total;
    for (int i = 1; i <= total; ++i) {
        long long val = i * X / Y;
        evaluate(val - 1, i);
        evaluate(val, i);
        evaluate(val + 1, i);
    }
    cout << numerator << "/" << denominator;
    return 0;
}
